const express = require('express');
const crypto = require('crypto');
const fs = require('fs');
const path = require('path');

const app = express();
app.use(express.json());

// Key management
const KEY_DIR = path.resolve(__dirname, 'keys');
let rsaPublicKey = null;
let rsaPrivateKey = null;
let hmacSecret = null;

function initKeys() {
  const pubKeyPath = path.join(KEY_DIR, 'rsa_public.pem');
  const privKeyPath = path.join(KEY_DIR, 'rsa_private.pem');
  if (fs.existsSync(pubKeyPath) && fs.existsSync(privKeyPath)) {
    rsaPublicKey = fs.readFileSync(pubKeyPath, 'utf8');
    rsaPrivateKey = fs.readFileSync(privKeyPath, 'utf8');
  } else {
    const { publicKey, privateKey } = crypto.generateKeyPairSync('rsa', {
      modulusLength: 2048,
      publicKeyEncoding: { type: 'spki', format: 'pem' },
      privateKeyEncoding: { type: 'pkcs8', format: 'pem' }
    });
    fs.mkdirSync(KEY_DIR, { recursive: true });
    fs.writeFileSync(pubKeyPath, publicKey);
    fs.writeFileSync(privKeyPath, privateKey);
    rsaPublicKey = publicKey;
    rsaPrivateKey = privateKey;
  }
  hmacSecret = crypto.randomBytes(32);
}

initKeys();

// Token utilities
function base64UrlEncode(buf) {
  return Buffer.from(buf).toString('base64')
    .replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function base64UrlDecode(str) {
  str = str.replace(/-/g, '+').replace(/_/g, '/');
  while (str.length % 4) str += '=';
  return Buffer.from(str, 'base64');
}

function createToken(payload, options = {}) {
  const alg = options.algorithm || 'RS256';
  const header = { alg, typ: 'JWT' };
  const headerB64 = base64UrlEncode(JSON.stringify(header));
  const payloadB64 = base64UrlEncode(JSON.stringify(payload));
  const signingInput = `${headerB64}.${payloadB64}`;
  let signature;
  if (alg === 'RS256') {
    const sign = crypto.createSign('RSA-SHA256');
    sign.update(signingInput);
    signature = sign.sign(rsaPrivateKey);
  } else if (alg === 'HS256') {
    signature = crypto.createHmac('sha256', hmacSecret).update(signingInput).digest();
  } else {
    throw new Error(`Unsupported algorithm: ${alg}`);
  }
  return `${signingInput}.${base64UrlEncode(signature)}`;
}

// Verification uses ONLY the expected algorithm, never trusts the header
const VERIFY_ALGORITHM = 'RS256';

function verifyToken(token) {
  const parts = token.split('.');
  if (parts.length !== 3) return { valid: false, error: 'malformed token' };

  let header;
  try {
    header = JSON.parse(base64UrlDecode(parts[0]).toString());
  } catch (e) {
    return { valid: false, error: 'invalid header' };
  }

  // Enforce server-side algorithm - ignore client-specified algorithm
  if (header.alg !== VERIFY_ALGORITHM) {
    return { valid: false, error: 'algorithm mismatch' };
  }

  const signingInput = `${parts[0]}.${parts[1]}`;
  const signature = base64UrlDecode(parts[2]);

  let verified = false;
  const verify = crypto.createVerify('RSA-SHA256');
  verify.update(signingInput);
  verified = verify.verify(rsaPublicKey, signature);

  if (!verified) return { valid: false, error: 'invalid signature' };

  let payload;
  try {
    payload = JSON.parse(base64UrlDecode(parts[1]).toString());
  } catch (e) {
    return { valid: false, error: 'invalid payload' };
  }

  // Check expiration
  if (payload.exp && Date.now() / 1000 > payload.exp) {
    return { valid: false, error: 'token expired' };
  }

  return { valid: true, payload };
}

// Rate limiting with sliding window
const rateLimits = new Map();
function rateLimit(ip, maxRequests = 100, windowMs = 60000) {
  const now = Date.now();
  if (!rateLimits.has(ip)) rateLimits.set(ip, []);
  const timestamps = rateLimits.get(ip).filter(t => now - t < windowMs);
  timestamps.push(now);
  rateLimits.set(ip, timestamps);
  return timestamps.length <= maxRequests;
}

// Middleware
function authMiddleware(req, res, next) {
  const authHeader = req.headers.authorization;
  if (!authHeader || !authHeader.startsWith('Bearer ')) {
    return res.status(401).json({ error: 'missing authorization' });
  }
  const token = authHeader.slice(7);
  const result = verifyToken(token);
  if (!result.valid) {
    return res.status(401).json({ error: result.error });
  }
  req.user = result.payload;
  next();
}

function rateLimitMiddleware(req, res, next) {
  const ip = req.ip || req.connection.remoteAddress;
  if (!rateLimit(ip)) {
    return res.status(429).json({ error: 'rate limited' });
  }
  next();
}

// Routes
app.post('/auth/login', rateLimitMiddleware, (req, res) => {
  const { username, password } = req.body;
  // Simplified auth - in production use bcrypt comparison against DB
  if (!username || !password || password.length < 8) {
    return res.status(401).json({ error: 'invalid credentials' });
  }
  const payload = {
    sub: username,
    role: username === 'admin' ? 'admin' : 'user',
    iat: Math.floor(Date.now() / 1000),
    exp: Math.floor(Date.now() / 1000) + 3600
  };
  const token = createToken(payload, { algorithm: 'RS256' });
  res.json({ token });
});

app.get('/auth/public-key', rateLimitMiddleware, (req, res) => {
  res.type('text/plain').send(rsaPublicKey);
});

app.get('/api/profile', authMiddleware, (req, res) => {
  res.json({ user: req.user });
});

app.get('/api/admin/users', authMiddleware, (req, res) => {
  if (req.user.role !== 'admin') {
    return res.status(403).json({ error: 'admin only' });
  }
  res.json({ users: ['admin', 'user1', 'user2'] });
});

app.listen(3000);
module.exports = app;
